local a={}a.SPIN_IDLE={"|","/","-","\\"}a.SPIN_RUN={"<","^",">","v"}function a.phase(b)b=b or{}if b.engaged then return"RUNNING"end;if type(b.elapsedMs)~="number"then return"LOADING"end;if b.elapsedMs<(b.warmupMs or 0)then return"WARMUP"end;return"IDLE"end;function a.spinner(c,d)local e=d=="running"and a.SPIN_RUN or a.SPIN_IDLE;local f=math.floor(c or 0)%#e+1;return e[f]end;function a.statusLine(g,h)if g=="LOADING"then return"FCS LOADING..."end;if g=="WARMUP"then return"FCS WARM UP..."end;if g=="RUNNING"then return"FCS RUNNING: "..tostring(h or"")end;return"FCS IDLE: "..tostring(h or"")end;function a.logLine(i)if not i then return""end;return"LOGGING: ON   P to log and upload"end;return a